#include <iostream>
#include <cmath>
using namespace std;

long long A, B, C;

long long find_gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> A >> B >> C;

    if (B <= C) {
        long long g = find_gcd(A, B);
        A /= g;
        B /= g;
        cout << A << "/" << B;
        return 0;
    }
    if (A == B) {
        cout << "1/1";
        return 0;
    }

    double min_difference = 1e18;
    double ratio_value = double(A) / double(B);
    long long numerator_result, denominator_result;
    long long left_limit = 0, right_limit = B;
    for (long long i = 1; i <= C; ++i) {
        while (i * A > right_limit) {
            left_limit += B;
            right_limit += B;
        }
        if (i * A >= left_limit && i * A <= right_limit) {
            long long low_bound = left_limit / B;
            long long high_bound = right_limit / B;
            double low_ratio = double(low_bound) / double(i);
            double high_ratio = double(high_bound) / double(i);
            double diff_low = abs(ratio_value - low_ratio);
            double diff_high = abs(ratio_value - high_ratio);
            if (diff_high < diff_low) {
                if (diff_high < min_difference) {
                    min_difference = diff_high;
                    numerator_result = high_bound;
                    denominator_result = i;
                }
            } else {
                if (diff_low < min_difference) {
                    min_difference = diff_low;
                    numerator_result = low_bound;
                    denominator_result = i;
                }
            }
        }
    }
    long long g = find_gcd(numerator_result, denominator_result);
    numerator_result /= g;
    denominator_result /= g;
    cout << numerator_result << "/" << denominator_result;
    return 0;
}
